import{_ as o,o as s,c as n,ag as i}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-23（量子计算 / 容错）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/quantum-physics/science-daily-2026-10-23-quantum.md","filePath":"topics/quantum-physics/science-daily-2026-10-23-quantum.md"}'),e={name:"topics/quantum-physics/science-daily-2026-10-23-quantum.md"};function c(r,t,a,d,l,g){return s(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="科学日报-·-2026-10-23-量子计算-容错" tabindex="-1">科学日报 · 2026-10-23（量子计算 / 容错） <a class="header-anchor" href="#科学日报-·-2026-10-23-量子计算-容错" aria-label="Permalink to &quot;科学日报 · 2026-10-23（量子计算 / 容错）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-23.md</code> — 第42期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-quantum</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（延续 10-21 起的确立做法）。</p></blockquote><hr><h2 id="科学日报-2026-10-23-超导处理器上的「魔法态培育」——误差降低-40-倍、保真度-≥0-9999-1" tabindex="-1">科学日报 2026-10-23：超导处理器上的「魔法态培育」——误差降低 40 倍、保真度 ≥0.9999(1) <a class="header-anchor" href="#科学日报-2026-10-23-超导处理器上的「魔法态培育」——误差降低-40-倍、保真度-≥0-9999-1" aria-label="Permalink to &quot;科学日报 2026-10-23：超导处理器上的「魔法态培育」——误差降低 40 倍、保真度 ≥0.9999(1)&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-23.md</code> ｜ DOI: 10.1126/science.aee7961</p></blockquote><ul><li>问题：<strong>容错量子计算需要通用门集</strong>，但必需的<strong>非 Clifford 门</strong>在多数量子纠错架构里是<strong>巨大的资源开销</strong>。</li><li>方案对比：<strong>魔法态培育（magic state cultivation）</strong> 被视为比<strong>资源密集的蒸馏协议（distillation）</strong> 更高效的替代方案 —— 但要检验其假设，<strong>必须离开常规的量子存储实验范式</strong>（这才是它此前一直是「提案」的原因）。</li><li>本条做了什么（三件事）： <ul><li>在<strong>超导量子处理器</strong>上<strong>实验实现培育</strong>；</li><li>实现 <strong>code-switching</strong>（<strong>切换到表面码</strong>）；</li><li>开发<strong>容错测量协议</strong>来为魔法态保真度<strong>定界</strong>。</li></ul></li><li>结果：培育<strong>把误差降低 40 倍</strong>，态保真度<strong>至少 0.9999(1)</strong>，同时<strong>保留 8% 的尝试次数</strong>。</li><li>结论：从实验上确立魔法态培育是应对量子计算最重要挑战之一的<strong>可行方案</strong>（把「提案」变成「实验结果」）。</li><li>洞察（对本库 <code>quantum-physics</code>）：本条与本库 10-10「中性原子 99.854% 保真度纠缠门」构成<strong>同一问题的两个抓手</strong> —— 前者是<strong>把门本身做准</strong>，本条是<strong>用编码+培育把「准」造出来</strong>。更值得注意的是它标出的<strong>取舍</strong>：<strong>误差 ↓40× 的代价是丢弃 92% 的尝试</strong>。这与本库反复出现的「<strong>机制与数字分账</strong>」是同一条：<strong>保真度不是一个数，而是「质量 × 产出率」的二维前沿</strong>；读任何「容错里程碑」都应连读这两个坐标，否则「0.9999 保真度」与「只剩 8%」会被压扁成一句好话。对照库内 10-09「低对称石墨烯量子整流器」：都是<strong>把纠错/校正的责任从器件转移到架构层</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/quantum-physics/index.md</code> ｜ <code>topics/physics/quantum-computing-progress.md</code> ｜ 第42期 科学板块</p></blockquote><p>关键词：魔法态培育、magic state cultivation、非Clifford门、蒸馏协议distillation、容错量子计算、表面码、code-switching、容错测量、保真度定界、0.9999(1)、误差降40倍、保留8%尝试、质量产出率二维前沿、超导处理器</p><p>关联：<code>topics/quantum-physics/science-daily-2026-10-13.md</code>、<code>topics/quantum-physics/science-daily-2026-10-10.md</code>、<code>topics/physics/quantum-computing-progress.md</code>、<code>topics/physics/science-daily-2026-10-23-physics.md</code>、<code>topics/quantum-physics/index.md</code></p>',10)])])}const m=o(e,[["render",c]]);export{p as __pageData,m as default};
